<script>
import { mapGetters } from "vuex";
import moment from "moment";
import MoneyFormat from "@/utils/moneyFormat";
import NavBarVue from "@/components/NavBar";

export default {
  name: "UpcomingInstallmentsView",
  components: { NavBarVue },

  data: () => ({
    rangeFilter: "30",
    dateFrom: "",
    dateTo: "",
    currentPage: 1,
    perPage: 20,
    notifData: {
      customerName: "",
      phone: "",
      email: "",
      accountNumber: "",
      installmentOrder: 0,
      installmentAmount: 0,
    },
    notifMessage: "",
    notifChannels: ["sms"],
    sendingNotification: false,
    currentItem: null,
  }),

  created() {
    if (this.company && this.company.id) {
      this.$store.dispatch("getUpcomingInstallments", this.company.id);
    }
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "company",
      "customers",
      "upcomingInstallments",
    ]),

    dueToday() {
      const s = moment().startOf("day"),
        e = moment().endOf("day");
      return this.upcomingInstallments.filter((i) =>
        moment(i.dueDate).isBetween(s, e, undefined, "[]"),
      );
    },
    upcoming7() {
      const s = moment().startOf("day"),
        e = moment().add(7, "days").endOf("day");
      return this.upcomingInstallments.filter((i) =>
        moment(i.dueDate).isBetween(s, e, undefined, "[]"),
      );
    },
    upcoming30() {
      const s = moment().startOf("day"),
        e = moment().add(30, "days").endOf("day");
      return this.upcomingInstallments.filter((i) =>
        moment(i.dueDate).isBetween(s, e, undefined, "[]"),
      );
    },

    baseList() {
      if (this.rangeFilter === "today") return this.dueToday;
      if (this.rangeFilter === "7") return this.upcoming7;
      if (this.rangeFilter === "all") return this.upcomingInstallments;
      return this.upcoming30;
    },

    searchedList() {
      let r =
        this.dateFrom || this.dateTo
          ? this.upcomingInstallments
          : this.baseList;
      if (this.dateFrom) {
        const f = moment(this.dateFrom).startOf("day");
        r = r.filter((i) => moment(i.dueDate).isSameOrAfter(f));
      }
      if (this.dateTo) {
        const t = moment(this.dateTo).endOf("day");
        r = r.filter((i) => moment(i.dueDate).isSameOrBefore(t));
      }
      return r;
    },

    searchedTotal() {
      return this.searchedList.reduce((s, i) => s + (i.installment || 0), 0);
    },
    totalPages() {
      return Math.ceil(this.searchedList.length / this.perPage);
    },
    startIdx() {
      return (this.currentPage - 1) * this.perPage;
    },
    endIdx() {
      return Math.min(this.startIdx + this.perPage, this.searchedList.length);
    },
    paginatedList() {
      return this.searchedList.slice(this.startIdx, this.endIdx);
    },
  },

  watch: {
    rangeFilter() {
      this.currentPage = 1;
    },
    dateFrom() {
      this.currentPage = 1;
    },
    dateTo() {
      this.currentPage = 1;
    },
  },

  methods: {
    convertMoney(v) {
      return MoneyFormat.formatMoney(v);
    },

    getCustomerName(accountNumber) {
      const c = this.customers.find((x) => x.accountNumber === accountNumber);
      return c ? c.customerName : accountNumber;
    },

    openCustomerPanel(accountNumber) {
      const c = this.customers.find((x) => x.accountNumber === accountNumber);
      if (c) {
        this.$store.commit("SET_CURRENT_CUSTOMER", c);
        this.$router.push("/customer");
      }
    },

    syncData() {
      if (this.company && this.company.id) {
        this.$store.dispatch("getUpcomingInstallments", this.company.id);
      }
    },

    clearFilters() {
      this.dateFrom = "";
      this.dateTo = "";
      this.currentPage = 1;
    },

    buildMessage(customer, item) {
      return `Prezado(a) ${
        customer.customerName
      },\n\nLembramos que a prestação nº ${
        item.installmentOrder
      } no valor de ${MoneyFormat.formatMoney(
        item.installment,
      )} vence em breve. Caso já tenha efectuado o pagamento, por favor desconsidere esta mensagem.\n\n${
        this.company.companyName
      }`;
    },

    openNotificationModal(item) {
      const customer = this.customers.find(
        (c) => c.accountNumber === item.accountNumber,
      );
      if (!customer) {
        this.$bvToast.toast("Cliente não encontrado.", {
          title: "Aviso!",
          variant: "warning",
          solid: true,
          toaster: "b-toaster-top-center",
        });
        return;
      }
      this.currentItem = item;
      this.notifData = {
        customerName: customer.customerName,
        phone: customer.customerPhone || "",
        email: customer.customerEmail || "",
        accountNumber: customer.accountNumber,
        installmentOrder: item.installmentOrder,
        installmentAmount: item.installment,
      };
      this.notifMessage = this.buildMessage(customer, item);
      this.notifChannels = ["sms"];
      this.$refs["notification-modal"].show();
    },

    resetMessage() {
      const customer = this.customers.find(
        (c) => c.accountNumber === this.notifData.accountNumber,
      );
      if (customer && this.currentItem)
        this.notifMessage = this.buildMessage(customer, this.currentItem);
    },

    async sendNotification() {
      this.sendingNotification = true;
      const results = [];
      try {
        if (this.notifChannels.includes("sms")) {
          if (!this.notifData.phone) {
            this.showToast(
              "Aviso!",
              "warning",
              "Telefone obrigatório para SMS.",
            );
            this.sendingNotification = false;
            return;
          }
          this.$store.dispatch("sendSMSMessage", {
            receipient: this.notifData.phone,
            accountNumber: this.notifData.accountNumber,
            sender: this.company.smsSender,
            companyId: this.company.id,
            smsBody: this.notifMessage,
          });
          results.push("SMS");
        }
        if (this.notifChannels.includes("whatsapp")) {
          if (!this.notifData.phone) {
            this.showToast(
              "Aviso!",
              "warning",
              "Telefone obrigatório para WhatsApp.",
            );
            this.sendingNotification = false;
            return;
          }
          window.open(
            `https://wa.me/${this.notifData.phone.replace(
              /\D/g,
              "",
            )}?text=${encodeURIComponent(this.notifMessage)}`,
            "_blank",
          );
          results.push("WhatsApp");
        }
        if (this.notifChannels.includes("email")) {
          if (!this.notifData.email) {
            this.showToast("Aviso!", "warning", "E-mail obrigatório.");
            this.sendingNotification = false;
            return;
          }
          window.open(
            `mailto:${this.notifData.email}?subject=${encodeURIComponent(
              "Lembrete de Prestação - " + this.company.companyName,
            )}&body=${encodeURIComponent(this.notifMessage)}`,
            "_blank",
          );
          results.push("E-mail");
        }
        if (results.length > 0) {
          this.showToast(
            "Sucesso!",
            "success",
            `Notificação enviada via: ${results.join(", ")}`,
          );
          this.$refs["notification-modal"].hide();
        }
      } catch (e) {
        this.showToast("Erro!", "danger", "Erro ao enviar notificação.");
      } finally {
        this.sendingNotification = false;
      }
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(msg, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>

